import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

/**
 * Noor & Bayan Academy Server Entrypoint
 * - In production (Cloud Run / Node): Imports the pre-bundled `dist-server/server.js` generated by `npm run build`.
 * - In development (`npm run dev`): Runs `src/server/main.ts` directly with Vite middleware.
 */
const bundledServer = path.resolve(process.cwd(), 'dist-server', 'server.js');
const isProd = process.env.NODE_ENV === 'production';
const isTsx = Boolean(
  process.env.TSX_TSCONFIG_PATH ||
  (process as any)[Symbol.for('tsx.loader')] ||
  process.execArgv.some((a) => a.includes('tsx'))
);

if (fs.existsSync(bundledServer) && (isProd || !isTsx)) {
  await import(pathToFileURL(bundledServer).href);
} else {
  await import('./src/server/main.ts');
}
